xpath.script:
(function(){
    // Topbar dropdowns — country, language, currency
    // Restore saved values on load using data-storage-key on wrapper div
    document.querySelectorAll('.av-tb-dropdown[data-storage-key]').forEach(function(dd){
        var key = dd.getAttribute('data-storage-key');
        var saved = localStorage.getItem(key);
        if(!saved) return;
        var trigger = dd.querySelector('.av-tb-trigger');
        if(!trigger) return;
        // update trigger text (first text node)
        var textNode = trigger.firstChild;
        if(textNode && textNode.nodeType === 3) textNode.textContent = saved + ' ';
        // mark selected item
        dd.querySelectorAll('.av-tb-dropdown-item').forEach(function(item){
            item.classList.remove('av-tb-selected');
            if(item.getAttribute('data-val') === saved) item.classList.add('av-tb-selected');
        });
    });

    // Wire up all tb-dropdowns
    document.querySelectorAll('.av-tb-dropdown').forEach(function(dd){
        var trigger = dd.querySelector('.av-tb-trigger');
        if(!trigger) return;
        trigger.addEventListener('click', function(e){
            e.stopPropagation();
            var isOpen = dd.classList.contains('open');
            document.querySelectorAll('.av-tb-dropdown.open').forEach(function(d){ d.classList.remove('open'); });
            if(!isOpen) {
                dd.classList.add('open');
                var sel = dd.querySelector('.av-tb-selected');
                if(sel) setTimeout(function(){ sel.scrollIntoView({block:'nearest'}); }, 50);
            }
        });
        // item selection — save to localStorage and sync mobile
        var storageKey = dd.getAttribute('data-storage-key');
        dd.querySelectorAll('.av-tb-dropdown-item').forEach(function(item){
            item.addEventListener('click', function(e){
                if(item.tagName === 'A') {
                    // language/currency links — update label then let navigate
                    e.stopPropagation();
                    var val = item.querySelector('.av-tb-dd-name') ? item.querySelector('.av-tb-dd-name').textContent.trim() : '';
                    if(val) {
                        var textNode = trigger.firstChild;
                        if(textNode && textNode.nodeType === 3) textNode.textContent = val + ' ';
                    }
                    dd.classList.remove('open');
                    return; // let href navigate
                }
                e.stopPropagation();
                dd.querySelectorAll('.av-tb-dropdown-item').forEach(function(i){ i.classList.remove('av-tb-selected'); });
                item.classList.add('av-tb-selected');
                var val = item.getAttribute('data-val') || item.querySelector('.av-tb-dd-name').textContent.trim();
                // update trigger label
                var textNode = trigger.firstChild;
                if(textNode && textNode.nodeType === 3) textNode.textContent = val + ' ';
                // persist (country only — currency uses pricelist links)
                if(storageKey) localStorage.setItem(storageKey, val);
                // sync mobile country val display
                if(storageKey === 'av_country') {
                    var mobileValEl = document.getElementById('av-country-val');
                    if(mobileValEl) mobileValEl.textContent = val;
                    var mobileDd = document.getElementById('av-country-dropdown');
                    if(mobileDd) {
                        mobileDd.querySelectorAll('.av-settings-dropdown-item').forEach(function(i){
                            i.classList.remove('selected');
                            if(i.getAttribute('data-val') === val) i.classList.add('selected');
                        });
                    }
                }
                dd.classList.remove('open');
            });
        });
    });

    // Close on outside click
    document.addEventListener('click', function(){
        document.querySelectorAll('.av-tb-dropdown.open').forEach(function(d){ d.classList.remove('open'); });
    });
})();

(function(){
    // Current date in topbar
    (function(){
        var el = document.getElementById('av-topbar-date');
        if(!el) return;
        var d = new Date();
        var days = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
        var months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
        var dateStr = days[d.getDay()] + ', ' + months[d.getMonth()] + ' ' + String(d.getDate()).padStart(2,'0') + ', ' + d.getFullYear();
        el.innerHTML = '' + dateStr + ''
            + '|'
            + ''
            + ''
            + 'Detecting…'
            + '';

        // DEBUG bar — uncomment to enable location debugging
        // (function(){
        //     var dbgBar = document.createElement('div');
        //     dbgBar.id = 'av-loc-debug';
        //     dbgBar.style.cssText = 'position:fixed;bottom:0;left:0;right:0;background:#111;color:#0f0;font-size:13px;padding:6px 12px;z-index:99999;font-family:monospace;white-space:nowrap;overflow:hidden;';
        //     dbgBar.textContent = 'Location: waiting...';
        //     document.addEventListener('DOMContentLoaded', function(){ document.body.appendChild(dbgBar); });
        // })();
        // function avLocDebug(msg) {
        //     var el = document.getElementById('av-loc-debug');
        //     if(el) el.textContent = msg;
        // }

        function avSetLocationSession(countryCode) {
            fetch('/aveenix/location/set', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({jsonrpc:'2.0',method:'call',id:1,params:{country_code: countryCode}})
            }).catch(function(){});
        }

        var avLocEl = document.getElementById('av-topbar-location');

        function avSetCityText(text) {
            var cityEl = document.getElementById('av-topbar-city');
            if(cityEl) {
                cityEl.textContent = text;
            } else if(avLocEl) {
                avLocEl.innerHTML = ''
                    + '' + text + '';
            }
            var mobileVal = document.getElementById('av-mobile-location-val');
            if(mobileVal) mobileVal.textContent = text;
        }

        window.avMobileLocationTap = function() {
            var mobileVal = document.getElementById('av-mobile-location-val');
            if(mobileVal) mobileVal.textContent = 'Detecting…';
            avDetectLocation(true);
        };

        function avShowLocationBtn() {
            if(!avLocEl) return;
            avLocEl.innerHTML = ''
                + 'Enable location';
            document.getElementById('av-enable-location').addEventListener('click', function() {
                avLocEl.innerHTML = ''
                    + 'Detecting…';
                avDetectLocation(true);
            });
        }

        function avDetectLocation(fromBtn) {
            navigator.geolocation.getCurrentPosition(function(pos) {
                fetch('https://nominatim.openstreetmap.org/reverse?format=json&lat=' + pos.coords.latitude + '&lon=' + pos.coords.longitude)
                    .then(function(r){ return r.json(); })
                    .then(function(data) {
                        var city = (data.address && (data.address.city || data.address.town || data.address.village || data.address.county)) || 'Unknown';
                        avSetCityText(city);
                        if(data.address && data.address.country_code) {
                            avSetLocationSession(data.address.country_code.toUpperCase());
                        }
                    })
                    .catch(function(){ avSetCityText('Unknown'); });
            }, function() {
                avShowLocationBtn();
            }, {timeout: 10000, maximumAge: fromBtn ? 0 : 300000, enableHighAccuracy: false});
        }

        document.addEventListener('DOMContentLoaded', function() {
            if(!navigator.geolocation) { avSetCityText('Unknown'); return; }
            fetch('/aveenix/location/get', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({jsonrpc:'2.0',method:'call',id:1,params:{}})
            }).then(function(r){ return r.json(); }).then(function(d) {
                var res = d.result || {};
                if(res.country_name) {
                    avSetCityText(res.country_name);
                } else {
                    avStartDetection();
                }
            }).catch(function() { avStartDetection(); });
        });

        function avStartDetection() {
            if(navigator.permissions) {
                navigator.permissions.query({name:'geolocation'}).then(function(result) {
                    if(result.state === 'denied') {
                        avShowLocationBtn();
                    } else {
                        avDetectLocation(false);
                    }
                    result.onchange = function() {
                        if(result.state === 'granted') avDetectLocation(true);
                        else if(result.state === 'denied') avShowLocationBtn();
                    };
                }).catch(function(){ avDetectLocation(false); });
            } else {
                avDetectLocation(false);
            }
        }
    })();

    // Save search to recent
    var form = document.querySelector('.av-search-overlay-form');
    if(form) {
        form.addEventListener('submit', function(){
            var val = document.getElementById('av-search-overlay-input').value.trim();
            if(!val) return;
            var recent = JSON.parse(localStorage.getItem('av_recent_searches') || '[]');
            recent = recent.filter(function(r){ return r !== val; });
            recent.unshift(val);
            recent = recent.slice(0, 8);
            localStorage.setItem('av_recent_searches', JSON.stringify(recent));
        });
    }

    // Show recent searches when overlay opens
    document.addEventListener('click', function(e){
        if(e.target.closest('.av-mobile-search-trigger')) {
            setTimeout(function(){
                avLoadRecent();
                var input = document.getElementById('av-search-overlay-input');
                if(input) input.focus();
            }, 100);
        }
    });

    window.avLoadRecent = function(){
        var recent = JSON.parse(localStorage.getItem('av_recent_searches') || '[]');
        var section = document.getElementById('av-recent-section');
        var tags = document.getElementById('av-recent-tags');
        if(!section || !tags) return;
        if(recent.length === 0){ section.style.display='none'; return; }
        section.style.display='block';
        tags.innerHTML = recent.map(function(r){
            return ''+r+'';
        }).join('');
    };

    window.avClearRecent = function(){
        localStorage.removeItem('av_recent_searches');
        var section = document.getElementById('av-recent-section');
        if(section) section.style.display='none';
    };

    // Close overlay on backdrop click
    var overlay = document.getElementById('av-search-overlay');
    if(overlay){
        overlay.addEventListener('click', function(e){
            if(e.target === overlay) overlay.classList.remove('active');
        });
    }

    // Active state on bottom nav based on current URL
    (function(){
        var path = window.location.pathname;
        // strip trailing slash except root
        if(path !== '/') path = path.replace(/\/$/, '');
        var active = null;
        if(path === '/') {
            active = 'home';
        } else if(path === '/shop') {
            active = 'shop';
        } else if(path.startsWith('/categories')) {
            active = 'category';
        } else if(path.startsWith('/shop/')) {
            active = 'shop';
        } else if(path.startsWith('/my/')) {
            active = 'account';
        }
        if(active) {
            var el = document.querySelector('.av-mobile-nav [data-nav="' + active + '"]');
            if(el) el.classList.add('active');
        }
    })();

    // Mobile settings — color panel toggle
    var colorRow = document.getElementById('av-mobile-color-row');
    var colorPanel = document.getElementById('av-mobile-color-panel');
    var colorChevron = document.getElementById('av-mobile-color-chevron');
    if(colorRow && colorPanel) {
        colorRow.addEventListener('click', function(){
            var open = colorPanel.style.display !== 'none';
            colorPanel.style.display = open ? 'none' : 'block';
            if(colorChevron) colorChevron.style.transform = open ? '' : 'rotate(180deg)';
            var col = colorPanel.closest('.av-footer-col');
            if(col) col.classList.toggle('color-panel-open', !open);
        });
    }

    // Settings dropdowns: country, language, currency
    (function(){
        var pairs = [
            ['av-country-row', 'av-country-dropdown', 'av_country'],
            ['av-lang-row',    'av-lang-dropdown',    null],
            ['av-currency-row','av-currency-dropdown', null]
        ];

        // Restore saved country value into mobile display
        pairs.forEach(function(pair){
            if(!pair[2]) return;
            var saved = localStorage.getItem(pair[2]);
            if(!saved) return;
            var row = document.getElementById(pair[0]);
            var dd  = document.getElementById(pair[1]);
            if(!row || !dd) return;
            var valEl = row.querySelector('.av-settings-val');
            if(valEl) valEl.textContent = saved;
            dd.querySelectorAll('.av-settings-dropdown-item').forEach(function(item){
                item.classList.remove('selected');
                if(item.getAttribute('data-val') === saved) item.classList.add('selected');
            });
        });
        pairs.forEach(function(pair){
            var row = document.getElementById(pair[0]);
            var dd  = document.getElementById(pair[1]);
            var storageKey = pair[2];
            if(!row || !dd) return;
            var valEl = row.querySelector('.av-settings-val');

            // Click on row header — toggle dropdown
            row.addEventListener('click', function(){
                var isOpen = dd.style.display !== 'none';
                pairs.forEach(function(p){
                    var d = document.getElementById(p[1]);
                    var r = document.getElementById(p[0]);
                    if(d) d.style.display = 'none';
                    if(r) r.classList.remove('open');
                });
                if(!isOpen) {
                    dd.style.display = 'block';
                    row.classList.add('open');
                    var sel = dd.querySelector('.selected');
                    if(sel) setTimeout(function(){ sel.scrollIntoView({block:'nearest'}); }, 50);
                }
            });

            // Click on item — select it and persist
            dd.querySelectorAll('.av-settings-dropdown-item').forEach(function(item){
                item.addEventListener('click', function(e){
                    if(item.tagName === 'A') return; // let links navigate
                    e.stopPropagation();
                    dd.querySelectorAll('.av-settings-dropdown-item').forEach(function(i){ i.classList.remove('selected'); });
                    item.classList.add('selected');
                    var val = item.getAttribute('data-val') || item.querySelector('.av-dd-name').textContent;
                    if(valEl) valEl.textContent = val;
                    if(storageKey) localStorage.setItem(storageKey, val);
                    // sync desktop topbar trigger label + selected state
                    if(storageKey) {
                        var tbDd = document.querySelector('.av-tb-dropdown[data-storage-key="' + storageKey + '"]');
                        if(tbDd) {
                            var tbTrigger = tbDd.querySelector('.av-tb-trigger');
                            if(tbTrigger) {
                                var tn = tbTrigger.firstChild;
                                if(tn && tn.nodeType === 3) tn.textContent = val + ' ';
                            }
                            tbDd.querySelectorAll('.av-tb-dropdown-item').forEach(function(i){
                                i.classList.remove('av-tb-selected');
                                if(i.getAttribute('data-val') === val) i.classList.add('av-tb-selected');
                            });
                        }
                    }
                    // close
                    dd.style.display = 'none';
                    row.classList.remove('open');
                });
            });
        });
    })();

    // Mobile dark mode toggle synced with main toggle
    var mobileDarkBtn = document.getElementById('av-dark-toggle-mobile');
    if(mobileDarkBtn) {
        mobileDarkBtn.addEventListener('click', function(){
            var mainToggle = document.getElementById('av-dark-toggle');
            if(mainToggle) mainToggle.click();
        });
    }

    // Sync mobile color dot + name with current theme
    (function(){
        var dot = document.getElementById('av-mobile-color-dot');
        var name = document.getElementById('av-mobile-color-name');
        var saved = localStorage.getItem('av_color_theme');
        var savedName = localStorage.getItem('av_color_name');
        if(dot && saved) dot.style.background = saved;
        if(name && savedName) name.textContent = savedName;
        // Color buttons in mobile settings panel
        document.querySelectorAll('#av-mobile-color-panel .av-color-btn-wrapper').forEach(function(btn){
            btn.addEventListener('click', function(){
                var color = btn.getAttribute('data-color');
                var cname = btn.getAttribute('data-name');
                // Trigger same logic as desktop picker
                var desktopBtn = document.querySelector('.av-color-grid .av-color-btn-wrapper[data-color="' + color + '"]');
                if(desktopBtn) { desktopBtn.click(); }
                else {
                    document.documentElement.style.setProperty('--av-red', color);
                    localStorage.setItem('av_color_theme', color);
                    localStorage.setItem('av_color_name', cname);
                }
                if(dot) dot.style.background = color;
                if(name) name.textContent = cname;
            });
        });
    })();

    // Footer accordion — mobile only
    document.querySelectorAll('.av-footer-toggle').forEach(function(heading){
        heading.addEventListener('click', function(){
            if(window.innerWidth > 767) return;
            var col = heading.closest('.av-footer-col');
            var isOpen = col.classList.contains('open');
            document.querySelectorAll('.av-footer-col.open').forEach(function(c){ c.classList.remove('open'); });
            if(!isOpen) col.classList.add('open');
        });
    });
})();

(function(){
    try {
        var r = document.documentElement;
        var theme = localStorage.getItem('av_theme');
        var prefersDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
        if (theme === 'dark' || (theme === null && prefersDark)) {
            r.setAttribute('data-theme', 'dark');
            r.setAttribute('data-bs-theme', 'dark');
        }
        var c = localStorage.getItem('av_primary_color');
        if (c) {
            r.style.setProperty('--av-red', c);
            r.style.setProperty('--av-red-dark', 'color-mix(in srgb, ' + c + ' 75%, black)');
            r.style.setProperty('--bs-primary', c);
        }
    } catch(e) {}
    // Anti-flash: mark fav/wish buttons before paint + update header badges.
    try {
        var favIds = JSON.parse(localStorage.getItem('av_fav_ids') || '[]');
        var wishIds = JSON.parse(localStorage.getItem('av_wish_ids') || '[]');
        function updateFavBadge() {
            favIds = JSON.parse(localStorage.getItem('av_fav_ids') || '[]');
            var badge = document.getElementById('av-fav-count');
            if (!badge) return;
            var n = favIds.length;
            badge.textContent = n;
            badge.style.display = n ? '' : 'none';
        }
        function updateWishBadge() {
            wishIds = JSON.parse(localStorage.getItem('av_wish_ids') || '[]');
            var badge = document.getElementById('av-wish-count');
            if (!badge) return;
            var n = wishIds.length;
            badge.textContent = n;
            badge.style.display = n ? '' : 'none';
        }
        function markBtn(el) {
            var id = String(el.dataset.productId || el.dataset.productTemplateId || '');
            if (!id) return;
            var icon = el.querySelector('.fa');
            var isFavBtn = el.classList.contains('av-add-to-fav') || el.classList.contains('o_add_wishlist_dyn');
            if (isFavBtn) {
                if (favIds.includes(id)) {
                    if (icon) { icon.classList.remove('fa-heart-o'); icon.classList.add('fa-heart'); }
                    el.classList.add('av-added-to-fav');
                } else {
                    if (icon) { icon.classList.remove('fa-heart'); icon.classList.add('fa-heart-o'); }
                    el.classList.remove('av-added-to-fav');
                }
            }
            if (el.classList.contains('av-add-to-wish')) {
                if (wishIds.includes(id)) {
                    if (icon) { icon.classList.remove('fa-star-o'); icon.classList.add('fa-star'); }
                    el.classList.add('av-added-to-wish');
                } else {
                    if (icon) { icon.classList.remove('fa-star'); icon.classList.add('fa-star-o'); }
                    el.classList.remove('av-added-to-wish');
                }
            }
        }
        function markAll() {
            document.querySelectorAll('.av-add-to-fav,.av-add-to-wish,.o_add_wishlist_dyn').forEach(markBtn);
            updateFavBadge();
            updateWishBadge();
        }
        function onFavChanged() {
            favIds = JSON.parse(localStorage.getItem('av_fav_ids') || '[]');
            document.querySelectorAll('.av-add-to-fav,.o_add_wishlist_dyn').forEach(markBtn);
            updateFavBadge();
        }
        function onWishChanged() {
            wishIds = JSON.parse(localStorage.getItem('av_wish_ids') || '[]');
            document.querySelectorAll('.av-add-to-wish').forEach(markBtn);
            updateWishBadge();
        }
        document.addEventListener('DOMContentLoaded', markAll);
        window.addEventListener('av-fav-changed', onFavChanged);
        window.addEventListener('av-wish-changed', onWishChanged);
        var obs = new MutationObserver(function(muts) {
            muts.forEach(function(m) {
                m.addedNodes.forEach(function(n) {
                    if (n.nodeType !== 1) return;
                    if (n.classList.contains('av-add-to-fav') || n.classList.contains('av-add-to-wish') || n.classList.contains('o_add_wishlist_dyn')) markBtn(n);
                    n.querySelectorAll && n.querySelectorAll('.av-add-to-fav,.av-add-to-wish,.o_add_wishlist_dyn').forEach(markBtn);
                });
            });
        });
        obs.observe(document.documentElement, { childList: true, subtree: true });
        window.addEventListener('load', function() { obs.disconnect(); });
    } catch(e) {}
    // All Categories dropdown toggle
    try {
        document.addEventListener('DOMContentLoaded', function() {
            var btn = document.getElementById('av-all-categories-btn');
            var drop = document.getElementById('av-cat-dropdown');
            if (!btn || !drop) return;
            btn.addEventListener('click', function(e) {
                e.stopPropagation();
                drop.classList.toggle('av-cat-open');
            });
            document.addEventListener('click', function() {
                drop.classList.remove('av-cat-open');
            });
            drop.addEventListener('click', function(e) { e.stopPropagation(); });
        });
    } catch(e) {}
})();
